class Solution {
public:
    vector<int> flipMatchVoyage(TreeNode* root, vector<int>& voyage) {
        vector<int> res;
        int i = 0;
        auto dfs = [&](auto& self, TreeNode* node) -> bool {
            if (!node) return true;
            if (node->val != voyage[i++]) return false;
            if (node->left && node->left->val != voyage[i]) {
                res.push_back(node->val);
                return self(self, node->right) && self(self, node->left);
            }
            return self(self, node->left) && self(self, node->right);
        };
        return dfs(dfs, root) ? res : vector<int>{-1};
    }
};

class Solution {
    private List<Integer> res = new ArrayList<>();
    private int i = 0;
    private boolean dfs(TreeNode node, int[] voyage) {
        if (node == null) return true;
        if (node.val != voyage[i++]) return false;
        if (node.left != null && node.left.val != voyage[i]) {
            res.add(node.val);
            return dfs(node.right, voyage) && dfs(node.left, voyage);
        }
        return dfs(node.left, voyage) && dfs(node.right, voyage);
    }
    public List<Integer> flipMatchVoyage(TreeNode root, int[] voyage) {
        if (dfs(root, voyage)) return res;
        return Arrays.asList(-1);
    }
}

var flipMatchVoyage = function(root, voyage) {
    const res = [];
    let i = 0;
    const dfs = (node) => {
        if (!node) return true;
        if (node.val !== voyage[i++]) return false;
        if (node.left && node.left.val !== voyage[i]) {
            res.push(node.val);
            return dfs(node.right) && dfs(node.left);
        }
        return dfs(node.left) && dfs(node.right);
    };
    return dfs(root) ? res : [-1];
};
